function validate([n, queries]) {
  if (!Number.isInteger(n) || n < 2 || n > 30) return 'n is a whole number from 2 to 30.';
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 100000) return 'queries needs 1 to 10^5 pairs.';
  const top = 2 ** n - 1;
  for (const q of queries) {
    if (!Array.isArray(q) || q.length !== 2) return 'Each query is a pair [a, b].';
    const [a, b] = q;
    if (!Number.isInteger(a) || !Number.isInteger(b) || a < 1 || b < 1 || a > top || b > top) return 'Query nodes are between 1 and 2^n - 1.';
    if (a === b) return 'The two nodes of a query must differ.';
  }
  return null;
}

