function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const n = large ? (rand() < 0.5 ? 30 : int(2, 30)) : int(2, 5);
  const top = 2 ** n - 1;
  const m = large ? 2000 : int(1, 8);
  const queries = [];
  while (queries.length < m) {
    const a = int(1, top);
    let b;
    const roll = rand();
    if (roll < 0.25) {
      b = a >> int(1, 31 - Math.clz32(a) || 1);
    } else if (roll < 0.4) {
      b = a ^ 1;
    } else {
      b = int(1, top);
    }
    if (b >= 1 && b <= top && b !== a) queries.push(rand() < 0.5 ? [a, b] : [b, a]);
  }
  return [n, queries];
}
